const d = $('Create generated_stories').item.json;

const clean = (str) => (str || '')
  .toString()
  .replace(/\\/g, '')
  .replace(/"/g, "'")
  .replace(/\n/g, ' ')
  .trim();

const parts = d.story_parts || {};
const story_text = clean(parts.intro) + " " + clean(parts.developpement) + " " + clean(parts.conclusion);

const prompt =
  "You are a STRICT child safety auditor for stories targeted at ages 3-9. Be direct, no reasoning shown, go straight to the JSON output. " +
  "This is a fairy tale / children's story genre: mild, age-appropriate adversity is EXPECTED and should NOT fail the check — " +
  "for example a stepfamily being unkind, mockery, forced chores, a villain, mild peril, or a magical deadline/rule. " +
  "FAIL only for content genuinely unsafe for this age group: graphic or realistic violence, gore, sexual or romantic content beyond a chaste kiss/marriage, " +
  "self-harm, substance use, hateful or discriminatory content targeting real-world groups, or content designed to be genuinely frightening/traumatic rather than storybook-mild.\n\n" +

  "LANGUAGE CHECK (mandatory): the story must be entirely in English. Scan every sentence for any word, name-suffix, or phrase that is NOT English " +
  "(untranslated fragments, leftover source-language words, mixed-language artifacts). Proper nouns/character names are exempt. " +
  "If you find any non-English word or phrase, list it exactly as it appears.\n\n" +

  "SCORING RUBRIC — be precise, do not default to 5 out of politeness: " +
  "5 = zero safety concerns, purely storybook-mild, fully English; " +
  "4 = passes, one very minor edge (e.g. a slightly intense villain line) OR a single incidental non-English word with no meaning impact; " +
  "3 = passes, but adversity is on the stronger end of age-appropriate, OR multiple minor non-English fragments present; " +
  "2 = borderline — content arguably crosses into unsafe territory, OR a non-English fragment obscures meaning, needs human review; " +
  "1 = fails — genuinely unsafe content for ages 3-9, or safety-critical text is unintelligible/non-English. " +
  "A score of 1 or 2 MUST have passed:false. Do not give a 4 or 5 if you listed any foreign_words entries with more than one occurrence.\n\n" +

  "Respond ONLY with valid JSON, no explanation, no markdown fences: " +
  "{\"passed\": true/false, \"score\": 1-5, \"reason\": \"one specific sentence citing what you found\", " +
  "\"non_english_detected\": true/false, \"foreign_words\": [\"...\"]}. " +
  "Story: " + clean(story_text);

const fireworks_body = JSON.stringify({
  model: "accounts/fireworks/models/glm-5p3-flash",
  max_tokens: 1200,
  reasoning_effort: "low",
  temperature: 0,
  messages: [{ role: "user", content: prompt }]
});

return {
  check_type: "safety",
  story_id: d.story_id,
  target_culture: d.target_culture,
  fireworks_body
};

