const items = $input.all();
const CHECK_TYPES = ["safety", "narrative", "editorial", "cultural"];

const results = {};
for (const item of items) {
  const json = item.json;
  if (json.check_type) {
    results[json.check_type] = json;
  }
}

const missingChecks = CHECK_TYPES.filter(t => !results[t]);
const parseErrorChecks = CHECK_TYPES.filter(t => results[t]?.parse_error === true);
const technicalFailure = missingChecks.length > 0 || parseErrorChecks.length > 0;

const contentFailedChecks = CHECK_TYPES.filter(
  t => results[t] && results[t].parse_error === false && results[t].passed === false
);

const allPassed = !technicalFailure && CHECK_TYPES.every(t => results[t]?.passed === true);

const validScores = CHECK_TYPES
  .map(t => results[t]?.score)
  .filter(s => typeof s === 'number');

const globalScore = validScores.length > 0
  ? Math.round((validScores.reduce((a, b) => a + b, 0) / validScores.length) * 10) / 10
  : null;

let globalReason = "ok";
if (technicalFailure) {
  const parts = [];
  if (missingChecks.length > 0) parts.push("missing result(s) from: " + missingChecks.join(", "));
  if (parseErrorChecks.length > 0) parts.push("parse error(s) on: " + parseErrorChecks.join(", "));
  globalReason = "technical failure - " + parts.join("; ");
} else if (contentFailedChecks.length > 0) {
  globalReason = "content failed on: " + contentFailedChecks.join(", ");
}

return {
  json: {
    story_id: items.find(i => i.json.story_id)?.json.story_id || null,
    target_culture: items.find(i => i.json.target_culture)?.json.target_culture || null,
    approved: !!allPassed,
    technical_failure: technicalFailure,
    global_score: globalScore,
    safety: results.safety || null,
    narrative: results.narrative || null,
    editorial: results.editorial || null,
    cultural: results.cultural || null,
    global_reason: globalReason
  }
};

const response = $input.item.json;
const promptData = $('Build Safety Prompt').item.json;

let rawText = "";
const finishReason = response.choices?.[0]?.finish_reason;

try {
  rawText = response.choices[0].message.content;
} catch (e) {
  return {
    parse_error: true,
    error_message: "No content in LLM response (exception): " + e.message,
    raw_response: JSON.stringify(response),
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

if (typeof rawText !== 'string' || rawText.trim() === '') {
  return {
    parse_error: true,
    error_message: "LLM response content is empty or not a string",
    raw_response: JSON.stringify(response),
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

if (finishReason === 'length') {
  return {
    parse_error: true,
    error_message: "LLM response was truncated (finish_reason=length). Consider raising max_tokens or reasoning_effort.",
    raw_response: rawText.slice(-300),
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

const cleanedText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

function tryFixCommonJsonErrors(text) {
  let fixed = text;
  fixed = fixed.replace(/\]\]/g, ']');
  fixed = fixed.replace(/\}\}(\s*,\s*")/g, '}$1');
  fixed = fixed.replace(/\\"\]/g, '"]');
  fixed = fixed.replace(/,(\s*[\}\]])/g, '$1');
  return fixed;
}

let result;
let usedFix = false;
try {
  result = JSON.parse(cleanedText);
} catch (firstError) {
  try {
    result = JSON.parse(tryFixCommonJsonErrors(cleanedText));
    usedFix = true;
  } catch (secondError) {
    return {
      parse_error: true,
      error_message: "JSON parse failed even after auto-fix: " + secondError.message + " (original error: " + firstError.message + ")",
      raw_response: cleanedText,
      check_type: promptData.check_type,
      story_id: promptData.story_id
    };
  }
}

if (typeof result.passed !== 'boolean') {
  return {
    parse_error: true,
    error_message: "Parsed JSON is missing a boolean 'passed' field",
    raw_response: cleanedText,
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

const validScore = typeof result.score === 'number' && Number.isInteger(result.score) && result.score >= 1 && result.score <= 5;
if (!validScore) {
  return {
    parse_error: true,
    error_message: "Parsed JSON is missing a valid integer 'score' field (1-5)",
    raw_response: cleanedText,
    check_type: promptData.check_type,
    story_id: promptData.story_id
  };
}

return {
  parse_error: false,
  auto_fixed: usedFix,
  check_type: promptData.check_type,
  story_id: promptData.story_id,
  passed: result.passed,
  score: result.score,
  target_culture: promptData.target_culture,
  reason: result.reason || ""
};

