  return {
    parse_error: true,
    error_message: "Adapted story response was truncated (finish_reason=length). Raise max_tokens or check reasoning_effort.",
    raw_response: rawText.slice(-300),
    story_id: promptData.story_id,
    target_culture: promptData.target_culture
  };
}

const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

function tryFixCommonJsonErrors(text) {
  let fixed = text;
  fixed = fixed.replace(/\]\]/g, ']');
  fixed = fixed.replace(/\}\}(\s*,\s*")/g, '}$1');
  fixed = fixed.replace(/\\"\]/g, '"]');
  fixed = fixed.replace(/,(\s*[\}\]])/g, '$1');
  return fixed;
}

let storyParts;
let usedFix = false;

try {
  storyParts = JSON.parse(cleanedText);
} catch (firstError) {
  try {
    storyParts = JSON.parse(tryFixCommonJsonErrors(cleanedText));
    usedFix = true;
  } catch (secondError) {
    return {
      parse_error: true,
      error_message: "JSON parse failed even after auto-fix: " + secondError.message + " (original error: " + firstError.message + ")",
      raw_response: cleanedText,
      story_id: promptData.story_id,
      target_culture: promptData.target_culture
    };
  }
}

const requiredKeys = ["intro", "developpement", "conclusion"];
const missingKeys = requiredKeys.filter(k => typeof storyParts[k] !== 'string' || storyParts[k].trim() === '');

if (missingKeys.length > 0) {
  return {
    parse_error: true,
    error_message: "Parsed JSON missing or empty required field(s): " + missingKeys.join(", "),
    raw_response: cleanedText,
    story_id: promptData.story_id,
    target_culture: promptData.target_culture
  };
}

return {
  parse_error: false,
  auto_fixed: usedFix,
  story_id: promptData.story_id,
  title: promptData.title,
  target_culture: promptData.target_culture,
  original_text: promptData.original_text,
  story_parts: storyParts,
  created_at: new Date().toISOString()
};

const story = $input.item.json;

const story_id = story._id || story.id;
if (!story_id) {
  throw new Error('No story_id/id found on raw_stories item: ' + JSON.stringify(story));
}

const TARGET_CULTURES = [
  "Japanese",
  "Tunisian",
  "Italian"

];

const original_text = story.raw_text || story.full_text || story.story_text || '';
if (!original_text) {
  throw new Error('No story text field found on raw_stories item (checked raw_text/full_text/story_text): ' + JSON.stringify(story));
}

return TARGET_CULTURES.map(culture => ({
  json: {
    story_id,
    title: story.source_title || '',
    original_text,
    target_culture: culture
  }
}));
